function startingCharge(chores: number[][]): number {
  const n = chores.length, used = new Array(n).fill(false);
  let best = Infinity;
  const go = (count: number, spent: number, req: number) => {
    if (req >= best) return;
    if (count === n) { best = req; return; }
    for (let i = 0; i < n; i++) {
      if (used[i]) continue;
      used[i] = true;
      go(count + 1, spent + chores[i][0], Math.max(req, spent + chores[i][1]));
      used[i] = false;
    }
  };
  go(0, 0, 0);
  return best;
}

