class Solution:
    def startingCharge(self, chores: List[List[int]]) -> int:
        from itertools import permutations
        best = math.inf
        for order in permutations(chores):
            spent = req = 0
            for use, need in order:
                req = max(req, spent + need)
                spent += use
            best = min(best, req)
        return best

