function startingCharge(chores: number[][]): number {
  const order = [...chores].sort((a, b) => (b[1] - b[0]) - (a[1] - a[0]));
  let charge = 0;
  for (let i = order.length - 1; i >= 0; i--) {
    const [use, need] = order[i];
    charge = Math.max(charge + use, need);
  }
  return charge;
}

